# language: Python 3.11+
import zlib, base64
from pathlib import Path
_p = "".join(Path(__file__).with_name(f"s{i}.b64").read_text(encoding="utf-8") for i in range(31))
src = zlib.decompress(base64.b64decode(_p)).decode()
src = src.replace('    e.add_field(name="Slot",value=f"`{slot}` · {\', \'.join(SLOT_NAMES)}",inline=True)', '    e.add_field(name="Slot",value=f"`{slot}` · {\', \'.join(list_slots(uid))}",inline=True)')
src = src.replace('    @discord.ui.button(label="Open my config",style=discord.ButtonStyle.primary,custom_id="pre_open_v4",emoji="⚙️")\n    async def open_cfg(self,interaction:discord.Interaction,button:Button):\n        uid=interaction.user.id\n        user_cfg(uid)\n        await interaction.response.send_message(embed=build_preview_embed(uid),view=PreconfigView(uid),ephemeral=True)', '    @discord.ui.button(label="Open my config",style=discord.ButtonStyle.primary,custom_id="pre_open_v4",emoji="⚙️")\n    async def open_cfg(self,interaction:discord.Interaction,button:Button):\n        uid=interaction.user.id\n        try:\n            user_cfg(uid)\n            emb=build_preview_embed(uid)\n            view=PreconfigView(uid)\n            await interaction.response.send_message(embed=emb,view=view,ephemeral=True)\n        except Exception as e:\n            log.exception("open config")\n            msg=f"Open failed: `{type(e).__name__}: {e}`"\n            try:\n                if interaction.response.is_done():\n                    await interaction.followup.send(msg,ephemeral=True)\n                else:\n                    await interaction.response.send_message(msg,ephemeral=True)\n            except Exception:\n                pass')
exec(compile(src, "bot.py", "exec"), globals())
